import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { toast } from 'react-toastify';
import { User, Lock, Eye, EyeOff, Facebook, Twitter } from 'lucide-react';

const Login = () => {
  const [formData, setFormData] = useState({
    username: '',
    password: ''
  });
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [rememberMe, setRememberMe] = useState(false);
  const { login } = useAuth();

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    const result = await login(formData.username, formData.password);
    
    if (result.success) {
      toast.success('Login successful!');
    } else {
      toast.error(result.error);
    }
    
    setLoading(false);
  };

  return (
    <div className="auth-container flex">
      {/* Left Side - Illustration */}
      <div className="hidden lg:flex lg:w-1/2 auth-illustration items-center justify-center p-16">
        <div className="w-full max-w-lg">
          {/* Office Workspace Illustration */}
          <div className="office-illustration">
            {/* Wall with shelves */}
            <div className="office-wall">
              {/* Top shelf */}
              <div className="office-shelf top-6 left-12 w-40"></div>
              <div className="office-shelf-item top-3 left-14 w-8 h-8 bg-gray-300 rounded"></div>
              <div className="office-shelf-item top-3 left-24 w-8 h-8 bg-gray-300 rounded"></div>
              <div className="office-shelf-item top-3 left-34 w-6 h-6 bg-green-400 rounded-full"></div>
              
              {/* Bottom shelf */}
              <div className="office-shelf top-16 left-12 w-40"></div>
              <div className="office-shelf-item top-13 left-14 w-5 h-5 bg-blue-500 rounded"></div>
              <div className="office-shelf-item top-13 left-21 w-5 h-5 bg-blue-500 rounded"></div>
              <div className="office-shelf-item top-13 left-28 w-5 h-5 bg-blue-500 rounded"></div>
              <div className="office-shelf-item top-13 left-35 w-5 h-5 bg-yellow-400 rounded"></div>
            </div>
            
            {/* Desk */}
            <div className="office-desk">
              {/* Desk base */}
              <div className="office-desk-base"></div>
              
              {/* Plant on left */}
              <div className="office-plant top-6 left-8 w-8 h-10 bg-purple-600"></div>
              <div className="office-plant top-4 left-9 w-6 h-6 bg-green-400"></div>
              
              {/* Computer monitor */}
              <div className="office-monitor">
                <div className="office-monitor-screen">
                  <div className="absolute top-2 left-2 w-16 h-2 bg-blue-500 rounded"></div>
                  <div className="absolute top-5 left-2 w-1 h-1 bg-gray-400 rounded-full"></div>
                  <div className="absolute top-5 left-4 w-1 h-1 bg-gray-400 rounded-full"></div>
                  <div className="absolute top-5 left-6 w-1 h-1 bg-gray-400 rounded-full"></div>
                  <div className="absolute top-5 left-8 w-1 h-1 bg-gray-400 rounded-full"></div>
                  <div className="absolute top-7 left-2 w-12 h-1 bg-gray-300 rounded"></div>
                  <div className="absolute top-9 left-2 w-10 h-1 bg-gray-300 rounded"></div>
                </div>
              </div>
              
              {/* Tablet/Clipboard */}
              <div className="absolute top-10 left-40 w-10 h-12 bg-white rounded border border-gray-300">
                <div className="absolute top-2 left-2 w-6 h-1 bg-gray-400 rounded"></div>
                <div className="absolute top-3 left-2 w-6 h-1 bg-gray-400 rounded"></div>
                <div className="absolute top-4 left-2 w-6 h-1 bg-gray-400 rounded"></div>
                <div className="absolute top-5 left-2 w-2 h-1 bg-gray-400 rounded"></div>
                <div className="absolute top-5 left-5 w-2 h-1 bg-gray-400 rounded"></div>
              </div>
              
              {/* Filing cabinet */}
              <div className="absolute top-15 left-56 w-10 h-20 bg-gray-400 rounded">
                <div className="absolute top-2 left-1 w-8 h-3 bg-gray-500 rounded"></div>
                <div className="absolute top-6 left-1 w-8 h-3 bg-gray-500 rounded"></div>
                <div className="absolute top-10 left-1 w-8 h-3 bg-gray-500 rounded"></div>
                <div className="absolute top-14 left-1 w-8 h-3 bg-gray-500 rounded"></div>
              </div>
              
              {/* Person */}
              <div className="office-person">
                {/* Chair */}
                <div className="w-8 h-10 bg-purple-600 rounded"></div>
                {/* Person */}
                <div className="absolute -top-6 left-3 w-5 h-5 bg-gray-300 rounded-full"></div>
                <div className="absolute -top-4 left-2 w-6 h-8 bg-blue-800 rounded"></div>
                <div className="absolute top-2 left-2 w-6 h-5 bg-gray-600 rounded"></div>
              </div>
              
              {/* Plant on right */}
              <div className="office-plant top-6 right-8 w-10 h-16 bg-gray-400">
                <div className="office-plant top-0 left-2 w-8 h-8 bg-purple-500"></div>
                <div className="office-plant top-3 left-1 w-8 h-8 bg-purple-500"></div>
                <div className="office-plant top-6 left-3 w-8 h-8 bg-purple-500"></div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Right Side - Login Form */}
      <div className="w-full lg:w-1/2 auth-form-container flex items-center justify-center p-12">
        <div className="w-full max-w-md">
          <div className="text-center mb-8">
            <h2 className="auth-title text-4xl mb-4">Sign In</h2>
            <p className="auth-subtitle text-lg">
              Lorem ipsum dolor sit amet elit. Sapiente sit aut eos consectetur adipisicing.
            </p>
          </div>

          <form className="space-y-6" onSubmit={handleSubmit}>
            <div>
              <input
                id="username"
                name="username"
                type="text"
                required
                className="auth-input w-full px-4 py-4"
                placeholder="Username"
                value={formData.username}
                onChange={handleChange}
              />
            </div>
            
            <div>
              <input
                id="password"
                name="password"
                type={showPassword ? 'text' : 'password'}
                required
                className="auth-input w-full px-4 py-4"
                placeholder="Password"
                value={formData.password}
                onChange={handleChange}
              />
            </div>

            <div className="flex items-center justify-between">
              <label className="flex items-center">
                <input
                  type="checkbox"
                  checked={rememberMe}
                  onChange={(e) => setRememberMe(e.target.checked)}
                  className="auth-checkbox"
                />
                <span className="ml-2 text-gray-700 font-medium">Remember me</span>
              </label>
              <Link
                to="/forgot-password"
                className="auth-link"
              >
                Forgot Password
              </Link>
            </div>

            <button
              type="submit"
              disabled={loading}
              className="auth-button w-full py-4 px-6 text-white disabled:opacity-50"
            >
              {loading ? 'Signing in...' : 'Log In'}
            </button>

            <div className="auth-divider">
              <span>– or login with –</span>
            </div>

            <div className="flex justify-center space-x-4">
              <button
                type="button"
                className="social-button facebook"
              >
                <Facebook className="w-6 h-6" />
              </button>
              <button
                type="button"
                className="social-button twitter"
              >
                <Twitter className="w-6 h-6" />
              </button>
              <button
                type="button"
                className="social-button google"
              >
                <span className="text-lg font-bold">G</span>
              </button>
            </div>

            <div className="text-center">
              <p className="text-gray-600">
                Don't have an account?{' '}
                <Link
                  to="/register"
                  className="auth-link"
                >
                  Sign up here
                </Link>
              </p>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Login;
